'use strict';
// Модуль «Справочники» (организация)
/* ═════════════ Справочники (организация) ═════════════ */

function renderDicts(body,tab,fresh){
  if(tab==='types'){body.innerHTML=(Object.values(ORG.types).some(t=>t.on)?'':`<div class="note fe-note">${ic('book')}<span class="grow"><b>Подключённых видов отчётов пока нет.</b> Выберите из каталога платформы те, что сдают ваши контрагенты: по ним будут создаваться отчёты и напоминания.</span>${can('dicts')?`<button class="btn cta sm" id="dt-first">${ic('plus','sm')}Подключить из каталога</button>`:''}</div>`)+`<div class="note">${ic('info')}<span>Каталог видов отчётов один на всю платформу и его ведёт администратор. Организация подключает нужные виды и задаёт дни напоминаний. В день срока напоминание приходит всегда.</span></div><div id="dg"></div>`;
    grid($('#dg',body),{id:'dict-types',cols:[
      {key:'on',label:'Подключён',type:'enum',w:110,val:t=>ORG.types[t.id]&&ORG.types[t.id].on?'Да':'Нет',html:t=>`<input type="checkbox" class="sw" data-con="${t.id}" ${ORG.types[t.id]&&ORG.types[t.id].on?'checked':''} ${can('dicts')?'':'disabled'} aria-label="Подключить ${esc(t.name)}">`},
      {key:'name',label:'Вид отчёта',type:'text',w:280,val:t=>t.name,html:t=>`<span class="strong">${esc(t.name)}</span>`},
      {key:'act',label:'Что сделать',type:'enum',w:175,val:t=>ACT_L[t.act],html:t=>actPill(t.act,1)},{key:'pays',label:'Что уплачивается',type:'text',w:220,val:t=>paysTxt(t),html:t=>t.act==='sub'?'<span class="faint">—</span>':esc(paysTxt(t))},
      {key:'short',label:'Кратко',type:'text',w:100,val:t=>t.short},{key:'code',label:'Код формы',type:'text',w:110,val:t=>t.code,cls:'mono'},
      {key:'organ',label:'Орган',type:'enum',w:130,val:t=>t.organ},{key:'index',label:'Индекс формы',type:'text',w:110,val:t=>t.index||'',cls:'mono',hide:true},{key:'per',label:'Периодичность',type:'enum',w:120,val:t=>t.oneOff?'Разовый':PER_LABEL[t.per]},{key:'rule',label:'Срок сдачи',type:'text',w:250,val:t=>ruleText(t)},{key:'payrule',label:'Срок оплаты',type:'text',w:250,hide:true,val:t=>t.sum?payRuleText(t):''},
      // Переключатели «Файл при сдаче обязателен» и «Квитанция о приёме обязательна» — после срока, как в ТЗ (решение заказчика 27.10.2026, п. 44 расхождений продукта)
      {key:'file',label:'Файл при сдаче обязателен',type:'enum',w:200,val:t=>ORG.types[t.id]&&ORG.types[t.id].needFile?'Да':'Нет',html:t=>{const o=ORG.types[t.id];return o&&o.on&&t.act!=='pay'?`<input type="checkbox" class="sw" data-tf="needFile" data-tid="${t.id}" ${o.needFile?'checked':''} ${can('dicts')?'':'disabled'} aria-label="Файл при сдаче обязателен: ${esc(t.short)}">`:'<span class="faint">—</span>'}},{key:'rcpt',label:'Квитанция о приёме обязательна',type:'enum',w:230,val:t=>ORG.types[t.id]&&ORG.types[t.id].needReceipt?'Да':'Нет',html:t=>{const o=ORG.types[t.id];return o&&o.on?`<input type="checkbox" class="sw" data-tf="needReceipt" data-tid="${t.id}" ${o.needReceipt?'checked':''} ${can('dicts')?'':'disabled'} aria-label="Квитанция о приёме обязательна: ${esc(t.short)}">`:'<span class="faint">—</span>'}},
      {key:'kind',label:'Тип',type:'enum',w:110,val:t=>KIND_L[t.kind]},{key:'rates',label:'Ставки',type:'text',w:130,hide:true,val:t=>(t.rates||[]).join('; ')},{key:'used',label:'Назначено контрагентам',type:'int',w:110,num:true,val:t=>CPS.filter(c=>!c.archived&&c.assign.some(a=>a.t===t.id&&!a.to)).length},{key:'regimes',label:'Режимы',type:'text',w:160,hide:true,val:t=>t.regimes.join(', ')},
      {key:'days',label:'Напоминать за, дней',type:'text',w:150,val:t=>ORG.types[t.id]&&ORG.types[t.id].on?ORG.types[t.id].days.join(', ')+' и в день срока':'',html:t=>ORG.types[t.id]&&ORG.types[t.id].on?ORG.types[t.id].days.map(d=>`<span class="tag">${d}</span>`).join(' ')+' <span class="faint">+ в день</span>':'<span class="faint">—</span>'}],
      audit:t=>ORG.types[t.id]||t,rows:()=>RT.filter(t=>t.active),title:'name',noun:['вид','вида','видов'],rowClass:t=>ORG.types[t.id]&&ORG.types[t.id].on?'':'muted',open:typeSettingsDlg,sort:{key:'on',dir:-1},simulateLoad:fresh,
      actions:t=>[{label:'Описание и настройки',icon:'eye',run:()=>typeSettingsDlg(t)}]});
    if($('#dt-first',body))$('#dt-first',body).onclick=connectTypesDlg;
    body.addEventListener('change',e=>{const x=e.target;if(!x.dataset.tf)return;const o=ORG.types[x.dataset.tid];o[x.dataset.tf]=x.checked;touch(o);const t=T[x.dataset.tid];log('type',t.id,`${t.short}: ${x.dataset.tf==='needFile'?'файл при сдаче':'квитанция о приёме'} — ${x.dataset.tf==='needFile'?(x.checked?'обязателен':'не обязателен'):(x.checked?'обязательна':'не обязательна')}`);toast(`${t.short}: ${x.dataset.tf==='needFile'?'файл при сдаче':'квитанция о приёме'} ${x.checked?'обязательна':'не обязательна'}`)});
    body.addEventListener('change',e=>{const x=e.target;if(!x.dataset.con)return;const id=x.dataset.con;const t=T[id];
      if(!x.checked){const used=CPS.filter(c=>!c.archived&&c.assign.some(a=>a.t===id&&!a.to));if(used.length){x.checked=true;openModal({render:()=>({title:'Отключить нельзя',body:`<p style="margin:0">«${esc(t.name)}» назначен ${used.length} ${plural(used.length,'действующему контрагенту','действующим контрагентам','действующим контрагентам')}: ${esc(used.slice(0,5).map(c=>c.name).join(', '))}${used.length>5?' и другим':''}. Сначала снимите назначения на вкладке «Кто что сдаёт».</p>`,foot:'<button class="btn" data-close>Понятно</button><button class="btn cta" id="gm">Открыть «Кто что сдаёт»</button>',mount(el,m){$('#gm',el).onclick=()=>{m.close();go('reports','matrix')}}})});return}
        touch(ORG.types[id]);ORG.types[id].on=false;toast(`${t.short} отключён`)}
      else{ORG.types[id]=ORG.types[id]||born({days:[...ORG.remind],needFile:false,needReceipt:false});touch(ORG.types[id]);ORG.types[id].on=true;toast(`${t.short} подключён: напоминания за ${ORG.types[id].days.join(' и ')} дн.`)}
      log('org',id,`${x.checked?'Подключён':'Отключён'} вид отчёта «${t.name}»`);refreshAll()});
    return}
  const rows=()=>[...Object.values(DICT).flatMap(d=>d.items.filter(x=>x.active).map(x=>({d:d.title,name:x.name,o:x}))),...PHONES.map(p=>({d:'Коды стран телефонов',name:`${p.flag} ${p.name} +${p.code} · ${p.mask}`,o:p})),...holidayRows(+TODAY.slice(0,4)).map(h=>({d:'Производственный календарь',name:`${fmtD(h.d)} — ${h.name}`,o:h}))];
  // Справочники сгруппированы по смыслу (ТЗ «Группы справочников платформы»): плитка справочника открывает его значения с пояснениями
  const gs=orgDictGroups();
  body.innerHTML=`<div class="note">${ic('lock')}<span>Эти списки ведёт только администратор платформы. Организация выбирает из них значения. Если нужного значения нет — попросите добавить.</span><div class="grow" style="flex:1"></div><button class="btn sm" id="req">${ic('send','sm')}Попросить добавить</button></div>
    ${gs.map((g,gi)=>`<section class="dg-grp"><h3 class="dg-gh">${esc(g.group)}<span class="faint">${g.tabs.length}</span></h3><div class="dg-tiles">${g.tabs.map((t,ti)=>`<button type="button" class="dg-tile" data-dg="${gi}.${ti}"><span class="dg-tt"><b>${esc(t.tab)}</b><span class="tag">${t.n}</span></span><span class="dg-ta">${esc(t.about||'')}</span>${t.usedIn?`<span class="dg-tu">${esc(t.usedIn)}</span>`:''}</button>`).join('')}</div></section>`).join('')}
    <section class="dg-grp"><h3 class="dg-gh">Поиск по всем значениям</h3><div id="dpg"></div></section>`;
  body.querySelectorAll('[data-dg]').forEach(b=>b.onclick=()=>{const [gi,ti]=b.dataset.dg.split('.').map(Number);const t=Object.assign({group:gs[gi].group},gs[gi].tabs[ti]);if(t.go){location.hash='#dicts.'+t.go;return}orgDictDlg(t)});
  grid($('#dpg',body),{id:'dict-platform',rid:x=>x.d+'|'+x.name,audit:x=>x.o,cols:[{key:'d',label:'Справочник',type:'enum',w:230,val:x=>x.d},{key:'name',label:'Значение',type:'text',w:340,val:x=>x.name,html:x=>`<span class="strong">${esc(x.name)}</span>`}],rows,title:'name',noun:['значение','значения','значений'],sort:{key:'d',dir:1},simulateLoad:fresh});
  $('#req',body).onclick=requestDlg;
}
// Форма просмотра вида отчёта: описание и налоги, к которым он относится (dict-guide.js), отдельным блоком — настройки организации
function typeSettingsDlg(t){const o=ORG.types[t.id];const on=!!(o&&o.on);const ed=on&&can('dicts');const st={days:on?[...o.days]:[]};
  openModal({form:ed,size:'mid',kb:'Описание и настройки вида отчёта',render:m=>({title:esc(t.name),sub:`${esc(t.code||'без кода')} · ${esc(t.organ)} · ${esc(ruleText(t))}`,body:`${typeGuideHtml(t)}
    <section class="box tg-org"><h3>${ic('sliders','sm')}Настройки организации</h3>${on?`<div class="fld"><span class="lbl">Напоминать до срока, за дней</span><div class="row">${st.days.sort((a,b)=>b-a).map((d,i)=>`<span class="chip"><span>${d} ${plural(d,'день','дня','дней')}</span>${ed?`<button data-rm="${i}" aria-label="Убрать">${ic('x','sm')}</button>`:''}</span>`).join('')}${ed?'<input class="inp" id="ts-add" style="width:90px" inputmode="numeric" placeholder="+ день">':''}<span class="pill green">${ic('lock')}в день срока — всегда</span></div><div class="hint">Пустой набор — значит только в день срока.</div></div>
    <label class="check-row" ${t.act==='pay'?'hidden':''}><input type="checkbox" class="sw" id="ts-file" ${o.needFile?'checked':''} ${ed?'':'disabled'}><span class="grow">Файл при сдаче обязателен<div class="hint">Регулярную задачу нельзя закрыть без файла</div></span></label>
    <label class="check-row"><input type="checkbox" class="sw" id="ts-rcpt" ${o.needReceipt?'checked':''} ${ed?'':'disabled'}><span class="grow">Квитанция о приёме обязательна<div class="hint">При «Подтвердить» сдачу нужно приложить квитанцию о приёме органом (если подтверждение сдачи выключено в учётной политике — при «Сдан»)</div></span></label>`
    :`<div class="note">${ic('info')}<span>Вид не подключён. Включите переключатель «Подключён» в списке, чтобы назначать его контрагентам; после этого здесь появятся напоминания, файл и квитанция.</span></div>`}</section>`,
    foot:ed?`<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="ts-ok">Сохранить</button>`:'<button class="btn cta" data-close>Закрыть</button>',
    mount(el){if(!ed)return;$$('[data-rm]',el).forEach(b=>b.onclick=()=>{st.days.splice(+b.dataset.rm,1);m.draw()});const a=$('#ts-add',el);a.onkeydown=e=>{if(e.key==='Enter'){const n=+a.value;if(n>0&&n<=60&&!st.days.includes(n)){st.days.push(n);m.draw()}}};
      $('#ts-ok',el).onclick=()=>{const n=+a.value;if(n>0&&n<=60&&!st.days.includes(n))st.days.push(n);o.days=st.days.sort((x,y)=>y-x);o.needFile=$('#ts-file',el).checked;o.needReceipt=$('#ts-rcpt',el).checked;log('org',t.id,`Настройки «${t.short}»: напоминать за ${o.days.join(', ')||'—'} дн.`);m.close();refreshAll();toast('Настройки вида сохранены')}}})});
}
function requestDlg(){openModal({form:true,render:()=>({title:'Попросить добавить',sub:'Запрос уйдёт администратору платформы',body:`<div class="form">${fld('Справочник',sel('rq-d',[['types','Виды отчётов'],...Object.entries(DICT).map(([k,d])=>[k,d.title])],'types'),{id:'rq-d'})}${fld('Что добавить',inp('rq-v','','placeholder="Например: Отчёт по НДС на импорт услуг"'),{req:true,id:'rq-v'})}${fld('Комментарий',`<textarea class="inp" id="rq-c" style="min-height:60px"></textarea>`,{full:true,id:'rq-c'})}</div>`,
  foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="rq-ok">Отправить запрос</button>',mount(el,m){$('#rq-ok',el).onclick=()=>{if(!setErr(el,'rq-v',val(el,'rq-v')?'':'Опишите, что добавить'))return;REQUESTS.push({_cb:S.me,_ca:nowStamp(),at:TODAY,oid:ORG.id,org:ORG.name,what:val(el,'rq-v'),dict:$('#rq-d',el).selectedOptions[0].text,note:val(el,'rq-c').trim(),status:'Новый',answer:''});m.close();toast('Запрос отправлен администратору платформы','send',false,{label:'Мои запросы',run:myReqDlg})}}})})}
// «Мои запросы» (решение заказчика 27.10.2026, п. 46 расхождений продукта): запросы «Попросить добавить» всей организации, от новых к старым, только просмотр; ответ администратора виден здесь, отдельного уведомления нет
const REQ_ST={Новый:['yellow','circle'],Добавлено:['green','check'],Отклонено:['faint','ban']};
const myReqs=()=>REQUESTS.filter(r=>r.oid?r.oid===ORG.id:r.org===ORG.name);
// Кто отправил запрос: сотрудник своей организации или пользователь другой организации платформы (для «Админки»)
const reqBy=r=>empName(r._cb)||((typeof OTHER_USERS!=='undefined'?OTHER_USERS:[]).find(u=>u.login===r._cb)||{}).fio||whoName(r._cb);
const reqCols=()=>[{key:'dict',label:'Справочник',type:'enum',w:150,val:r=>r.dict},{key:'what',label:'Что добавить',type:'text',w:180,val:r=>r.what,html:r=>`<span class="strong">${esc(r.what)}</span>`},{key:'note',label:'Комментарий',type:'text',w:150,val:r=>r.note||'',html:r=>r.note?esc(r.note):'<span class="faint">—</span>'},{key:'by',label:'Отправил',type:'enum',w:120,val:reqBy},
  {key:'st',label:'Статус',type:'enum',w:125,val:r=>r.status,html:r=>pill(r.status,REQ_ST)},{key:'answer',label:'Ответ',type:'text',w:210,val:r=>r.answer||'',html:r=>r.answer?esc(r.answer):'<span class="faint">—</span>'}];
// Запрос целиком (только просмотр): длинный комментарий и ответ видны полностью, в том числе на телефоне
function reqViewDlg(r){openModal({render:()=>({title:esc(r.what),sub:`${esc(r.org)} · ${esc(r.dict)} · ${fmtD(r.at)}`,body:`<div class="kv">${[['Статус',pill(r.status,REQ_ST)],['Отправил',esc(reqBy(r))],['Комментарий',r.note?esc(r.note):'—',1],['Ответ',r.answer?esc(r.answer):'Ответа пока нет',1]].map(([k,v,w])=>`<div${w?' style="grid-column:1/-1"':''}><span class="k">${k}</span><span class="v">${v}</span></div>`).join('')}</div>`,foot:'<div class="grow"></div><button class="btn cta" data-close>Готово</button>'})})}
function myReqDlg(){openModal({size:'wide',render:()=>({title:'Мои запросы',sub:'Запросы организации администратору платформы: что просили и что он ответил',body:'<div id="mrq"></div>',foot:'<div class="grow"></div><button class="btn cta" data-close>Готово</button>',
  mount(el){grid($('#mrq',el),{id:'my-req',rid:r=>r._ca+r.what,cols:[{key:'at',label:'Дата',type:'date',w:100,val:r=>r.at},...reqCols()],
    rows:myReqs,title:'what',open:reqViewDlg,noun:['запрос','запроса','запросов'],sort:{key:'at',dir:-1},empty:{icon:'send',title:'Запросов пока нет',text:'Если нужного значения нет в справочнике, нажмите «Попросить добавить».'}})}})})}
const REQUESTS=DB.dictRequests;

